DO $$ DECLARE d text; t text; prefix text:=''; BEGIN SELECT pg_get_functiondef('public.gl_lines(date)'::regprocedure) INTO d; FOREACH t IN ARRAY ARRAY['sales','sale_payments','sale_items','refunds','grns','supplier_payments','supplier_returns','expenses','customer_payments','customer_adjustments','stock_movements','products','journal_entries','journal_lines'] LOOP d:=replace(d,'public.'||t,'scope_'||t); prefix:=prefix||'scope_'||t||' AS (SELECT * FROM public.'||t||' WHERE store_id=public.current_store_id()),'; END LOOP; d:=replace(d,'WITH s AS','WITH '||prefix||' s AS'); EXECUTE d; END $$;
CREATE OR REPLACE FUNCTION public.subscription_state() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN s.is_vendor_store OR s.billing_exempt THEN 'active' WHEN s.trial_ends_at IS NOT NULL AND now()<s.trial_ends_at THEN 'active' WHEN current_date<=st.paid_until THEN 'active' WHEN s.trial_ends_at IS NOT NULL AND st.paid_until<s.trial_ends_at::date THEN 'locked' WHEN current_date<=st.paid_until+st.grace_days THEN 'grace' ELSE 'locked' END FROM public.stores s JOIN public.settings st ON st.store_id=s.id WHERE s.id=public.current_store_id() $$;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.submit_subscription_payment(integer,text,text,text)'::regprocedure) INTO d; d:=replace(d,'from settings where id = 1','from settings where store_id=public.current_store_id()'); EXECUTE d; END $$;
CREATE OR REPLACE FUNCTION public.protect_vendor_store_identity() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF OLD.is_vendor_store AND (NOT NEW.is_vendor_store OR NOT NEW.billing_exempt) THEN RAISE EXCEPTION 'The vendor store stays permanently free'; END IF; IF auth.uid() IS NOT NULL AND (NEW.is_vendor_store IS DISTINCT FROM OLD.is_vendor_store OR NEW.billing_exempt IS DISTINCT FROM OLD.billing_exempt OR NEW.trial_started_at IS DISTINCT FROM OLD.trial_started_at OR NEW.trial_ends_at IS DISTINCT FROM OLD.trial_ends_at) THEN RAISE EXCEPTION 'Trial and exemption fields require vendor approval'; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_vendor_store_identity BEFORE UPDATE ON public.stores FOR EACH ROW EXECUTE FUNCTION public.protect_vendor_store_identity();